      <!-- Main Chat View -->
      <div class="grow flex gap-2 min-h-0 overflow-hidden" v-show="!isPRView">

        <div class="flex flex-col min-h-0 min-w-0" :class="previewFile ? 'w-1/2' : 'w-full'">

          <!-- ── Unified scroll container: messages + composer ── -->
          <ChatMessageList
